import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Nutzungsbedingungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/terms.md","filePath":"de/guide/terms.md","lastUpdated":1793173149000}`),a={name:`de/guide/terms.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="nutzungsbedingungen" tabindex="-1">Nutzungsbedingungen <a class="header-anchor" href="#nutzungsbedingungen" aria-label="Permalink to “Nutzungsbedingungen”">​</a></h1><p>Diese Bedingungen regeln Ihre Nutzung der Sudoku-Anwendung. Mit dem Herunterladen, der Installation oder der Nutzung von Sudoku erklären Sie sich mit diesen Bedingungen einverstanden. Wenn Sie nicht einverstanden sind, verwenden Sie die Anwendung nicht.</p><h2 id="lizenz-und-nutzung" tabindex="-1">Lizenz und Nutzung <a class="header-anchor" href="#lizenz-und-nutzung" aria-label="Permalink to “Lizenz und Nutzung”">​</a></h2><p>Sudoku wird zu den Lizenzbedingungen bereitgestellt, die jeder Version beiliegen. Ihnen wird eine beschränkte, nicht ausschließliche und nicht übertragbare Lizenz erteilt, die Anwendung im Einklang mit den Lizenzbedingungen auf Ihren Geräten zu nutzen.</p><h2 id="offline-first-design-mit-optionalen-cloud-funktionen" tabindex="-1">Offline-First-Design mit optionalen Cloud-Funktionen <a class="header-anchor" href="#offline-first-design-mit-optionalen-cloud-funktionen" aria-label="Permalink to “Offline-First-Design mit optionalen Cloud-Funktionen”">​</a></h2><p>Sudoku ist eine Offline-First-Anwendung. Alle Spieldaten — Einstellungen, Spielstand und Statistiken — werden standardmäßig lokal auf Ihrem Gerät gespeichert.</p><p>Zu den optionalen Cloud-Funktionen gehören:</p><ul><li><strong>iCloud-Synchronisierung</strong> (über CloudKit): Synchronisiert Daten über Ihren persönlichen iCloud-Account zwischen Ihren Apple-Geräten.</li><li><strong>Game Center</strong>: Bietet Ranglisten und Erfolge.</li><li><strong>„Weitere Apps“</strong>: Eine optionale Funktion, die eine Liste weiterer Apps abruft; es werden keine personenbezogenen Daten übertragen.</li></ul><p>Über die Daten hinaus, die von Apples iCloud- und Game-Center-Diensten verwaltet werden, wenn Sie diese ausdrücklich aktivieren, erheben wir keine personenbezogenen Daten.</p><h2 id="pflichten-der-nutzer" tabindex="-1">Pflichten der Nutzer <a class="header-anchor" href="#pflichten-der-nutzer" aria-label="Permalink to “Pflichten der Nutzer”">​</a></h2><ul><li>Nutzen Sie Sudoku rechtmäßig und im Einklang mit den geltenden Regeln.</li><li>Versuchen Sie nicht, die App unter Verstoß gegen die Lizenz zu dekompilieren, zurückzuentwickeln oder zu verändern.</li><li>Nutzen Sie die App nicht für rechtswidrige Zwecke.</li></ul><h2 id="datenschutz" tabindex="-1">Datenschutz <a class="header-anchor" href="#datenschutz" aria-label="Permalink to “Datenschutz”">​</a></h2><p>Bitte lesen Sie die Datenschutzerklärung für Informationen zum Umgang mit Daten. Kurz gesagt: Wir erheben keine Daten; optionale Cloud-Funktionen nutzen ausschließlich Apples iCloud- und Game-Center-Dienste und dies nur mit Ihrer ausdrücklichen Zustimmung.</p><h2 id="gewahrleistungsausschluss" tabindex="-1">Gewährleistungsausschluss <a class="header-anchor" href="#gewahrleistungsausschluss" aria-label="Permalink to “Gewährleistungsausschluss”">​</a></h2><p>Sudoku wird „wie besehen“ ohne jegliche Gewährleistung bereitgestellt. Soweit gesetzlich zulässig, lehnen die Maintainer alle ausdrücklichen, stillschweigenden, gesetzlichen oder sonstigen Gewährleistungen ab, einschließlich der Marktgängigkeit und der Eignung für einen bestimmten Zweck.</p><h2 id="haftungsbeschrankung" tabindex="-1">Haftungsbeschränkung <a class="header-anchor" href="#haftungsbeschrankung" aria-label="Permalink to “Haftungsbeschränkung”">​</a></h2><p>Soweit gesetzlich zulässig, haften die Maintainer nicht für mittelbare, zufällige, besondere, Folge- oder exemplarische Schäden, die aus Ihrer Nutzung der Anwendung entstehen.</p><h2 id="kundigung" tabindex="-1">Kündigung <a class="header-anchor" href="#kundigung" aria-label="Permalink to “Kündigung”">​</a></h2><p>Die Ihnen erteilten Rechte erlöschen automatisch, wenn Sie gegen diese Bedingungen verstoßen.</p><h2 id="anderungen" tabindex="-1">Änderungen <a class="header-anchor" href="#anderungen" aria-label="Permalink to “Änderungen”">​</a></h2><p>Wir können diese Bedingungen von Zeit zu Zeit aktualisieren. Die weitere Nutzung nach Änderungen gilt als Zustimmung zu den überarbeiteten Bedingungen.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to “Kontakt”">​</a></h2><p>Bei Fragen zu diesen Bedingungen eröffnen Sie ein Issue im Projekt-Repository: <code>https://github.com/sudoku-pro/sudoku-site/issues</code>.</p><p><em>Zuletzt aktualisiert: 2026-07-29</em></p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};